<template><section class="collaboration-todos app-panel" aria-labelledby="collaboration-todos-title"><header><div><h2 id="collaboration-todos-title">{{ supervisor?'协同审批待办':'我的协同进展' }}</h2><p>报告与额度申请分别处理 点击进入原业务页面核对</p></div><el-button text type="primary" :loading="loading" @click="refresh">刷新待办</el-button></header><div class="collaboration-todo-columns"><section v-for="group in groups" :key="group.key"><h3><AppIcon :name="group.icon" :size="17" />{{ group.label }}<span>{{ group.loaded?'本次 '+group.items.length+' 条':'待核对' }}</span></h3><p v-if="group.error" role="status">{{ group.error }}</p><ul v-else-if="group.items.length"><li v-for="row in group.items" :key="row.id"><router-link :to="row.to"><strong>{{ row.title }}</strong><small>{{ row.description }}</small><AppIcon name="ArrowRight" :size="14" /></router-link></li></ul><p v-else>{{ group.loaded?'当前查询未返回待办':'正在读取待办' }}</p><router-link :to="group.to" class="collaboration-todo-all">{{ group.link }}</router-link></section></div></section></template>
<script setup>
import { ref, computed, onMounted } from 'vue'
import { useUserStore } from '../stores/user'
import { captureAccountRequest } from '../api/request'
const request=captureAccountRequest()
import { useAccountOperationScope } from '../composables/useAccountOperationScope'
import { useResourceChanges } from '../composables/useResourceChanges'
const user=useUserStore(),supervisor=computed(()=>user.role==='SUPERVISOR'),loading=ref(false)
const reports=ref({items:[],loaded:false,error:''}),quota=ref({items:[],loaded:false,error:''})
const scope=useAccountOperationScope(()=>{reports.value={items:[],loaded:false,error:''};quota.value={items:[],loaded:false,error:''}}),read=scope.channel()
const unwrap=response=>response.data?.code===200?response.data.data:response.data
async function refresh(){
 const token=read.begin();loading.value=true
 await Promise.allSettled([
  request.get('/api/detection/reports',{params:{page:1,size:5,status:'SUBMITTED'},signal:token.signal}).then(response=>{const data=unwrap(response);if(!Array.isArray(data?.records))throw new Error('报告待办未完整读取');if(read.current(token))reports.value={loaded:true,error:'',items:data.records.filter(row=>!supervisor.value||String(row.ownerUserId)!==String(user.userId)).map(row=>({id:row.reportId,title:row.title||row.reportId,description:'待审批 · '+(row.ownerUsername||'编写账号未记录'),to:{path:'/quality/reports',query:{reportId:row.reportId}}}))}}).catch(()=>{if(read.current(token))reports.value={...reports.value,error:'报告待办暂不可读取 请到报告页核对'}}),
  request.get('/api/agent/model-quotas/applications',{params:{scope:supervisor.value?'team':'mine',status:'PENDING',limit:5},signal:token.signal}).then(response=>{const data=unwrap(response);if(!Array.isArray(data?.items))throw new Error('额度待办未完整读取');if(read.current(token))quota.value={loaded:true,error:'',items:data.items.map(row=>({id:row.id,title:row.modelId,description:'申请追加 '+row.requestedTokens+' token',to:{path:'/agent/model-quotas',query:{scope:supervisor.value?'team':'mine',status:'PENDING',applicationId:row.id}}}))}}).catch(()=>{if(read.current(token))quota.value={...quota.value,error:'额度待办暂不可读取 或当前环境尚未启用'}})
 ]);if(read.current(token))loading.value=false
}
useResourceChanges({domains:['QUALITY_REPORT','LLM_QUOTA_APPLICATION','MODEL_BUDGET'],refresh})
onMounted(refresh)
const groups=computed(()=>[{key:'report',icon:'DocumentChecked',label:supervisor.value?'待审报告':'已提交报告',...reports.value,to:'/quality/reports',link:'查看报告与审批'},{key:'quota',icon:'Cpu',label:supervisor.value?'待审额度申请':'待审个人额度',...quota.value,to:{path:'/agent/model-quotas',query:{scope:supervisor.value?'team':'mine',status:'PENDING'}},link:'查看模型与额度'}])
</script>
<style scoped>.collaboration-todos{padding:22px;margin:18px 0}.collaboration-todos>header{display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.collaboration-todos h2{font-size:18px;margin:0}.collaboration-todos p{font-size:12px;color:var(--app-text-secondary);line-height:1.8}.collaboration-todo-columns{display:grid;grid-template-columns:1fr 1fr;gap:28px}.collaboration-todo-columns h3{display:flex;align-items:center;gap:7px;font-size:14px}.collaboration-todo-columns h3 span{font-size:12px;color:var(--app-text-secondary);font-weight:400;margin-left:auto}.collaboration-todo-columns ul{list-style:none;padding:0;margin:0}.collaboration-todo-columns li{border-top:1px solid var(--app-border)}.collaboration-todo-columns li a{display:grid;grid-template-columns:1fr auto;gap:6px;padding:13px 0;color:var(--app-text);text-decoration:none}.collaboration-todo-columns li strong{font-size:13px;font-weight:500}.collaboration-todo-columns li small{grid-row:2;color:var(--app-text-secondary)}.collaboration-todo-columns li .el-icon{grid-column:2;grid-row:1/3;align-self:center;color:var(--app-primary)}.collaboration-todo-all{display:inline-flex;margin-top:13px;color:var(--app-primary);font-size:12px}.collaboration-todos a:focus-visible{outline:2px solid var(--app-primary);outline-offset:3px}@media(max-width:650px){.collaboration-todo-columns{grid-template-columns:1fr;gap:10px}.collaboration-todos{padding:15px}}</style>
